package com.aicharacter.v3;import java.util.*;
public final class ReunionEngine {private ReunionEngine(){}public static String contextKey(WorldState s,long away){if(away<60)return"brief";if(s.relationship.irritation+s.relationship.hurt>25)return"guarded";if(away>1440&&s.relationship.attachment>20)return"long_attached";return"ordinary";}
 public static HaruMind.Response process(WorldState s,long now){if(s==null||s.reunionContext==null||s.reunionContext.isEmpty()||s.lastAbsenceMinutes<=0)return new HaruMind.Response("",false);long away=s.lastAbsenceMinutes;MemoryEntry reunion=CognitionEngine.process(s,new Experience("reunion","The cat returned after an absence of "+away+" minutes.",away>180?.2:.05,away>1440?.75:.4).at(HaruPerception.currentPlaceId(s),"").with("cat").tag("reunion").tag("player"));CognitionEngine.reviseFromMemory(s,"cat_returns","usually_returns",1,away>180?.65:.3,reunion);List<MemoryEntry> refs=MemoryRetrievalEngine.retrieve(s,null,"cat","absence",4);double hurt=(s.relationship.irritation+s.relationship.hurt)/202.0,attach=s.relationship.attachment/101.0;ThoughtState t=new ThoughtState("cat_return","reunion",hurt>.3?"keep_distance":attach>.3?"acknowledge_cat":"continue_activity",.2,Math.min(1,.25+attach+hurt),now);t.relatedMemories.add(reunion.memoryId);for(MemoryEntry m:refs)t.relatedMemories.add(m.memoryId);s.thoughts.add(t);s.lastCatSeenAt=now;s.lastAbsenceMinutes=0;s.reunionContext="";s.persistentIntentionTarget="";s.intentionStartedAt=now;s.emotion.joy=Math.min(1,s.emotion.joy+attach*.25);s.emotion.anger=Math.min(1,s.emotion.anger+hurt*.18);boolean speak=shouldSpeak(s,away,attach,hurt);if(hurt>.32){s.currentIntention="keep_distance";s.haruActivity="keeping some distance while watching the cat";}else if(attach>.28&&away>180){s.currentIntention="approach_cat";s.haruActivity="looking toward the cat and moving a little closer";}else{s.haruActivity="noticing the cat while continuing what she was doing";}if(!speak)return new HaruMind.Response("",false);return new HaruMind.Response(LanguageEngine.reunion(s,away,attach,hurt),false);}
 private static boolean shouldSpeak(WorldState s,long away,double attach,double hurt){if(hurt>.45)return false;if(s.currentIntention.equals("sleep")||s.body.energy<18)return false;if(away<45&&attach<.3)return false;return attach+.25*(away>360?1:0)+s.personality.sociability*.2>hurt+.28;}}
